=== FILE: credit_counter_props.sv ===
// Formal properties for credit_counter, written from interface_spec.md.
// Each assertion checks one tagged requirement on the interface ports.
// Immediate assert/assume/cover only, inside always blocks, $past guarded.
`default_nettype none
module credit_counter_formal #(
    parameter integer MAX = 4
) (
    input wire clk,
    input wire rst_n,
    input wire take,
    input wire give
);
    wire [7:0] credits;
    wire       avail;
    wire       full;
    wire       err;

    credit_counter #(.MAX(MAX)) dut (
        .clk(clk),
        .rst_n(rst_n),
        .take(take),
        .give(give),
        .credits(credits),
        .avail(avail),
        .full(full),
        .err(err)
    );

    localparam [7:0] F_MAX = MAX;

    // First-cycle guard for $past.
    reg f_past_valid = 1'b0;
    always @(posedge clk)
        f_past_valid <= 1'b1;

    // Environment, the only assumption: the block is reset in the first
    // step (spec 3.1 defines the state only from reset). take and give are free.
    always @(*)
        if (!f_past_valid)
            assume(!rst_n);

    // CC-RANGE: credits never above MAX (also the induction helper).
    always @(*)
        if (f_past_valid)
            assert(credits <= F_MAX);

    // CC-STATUS: avail and full follow credits with no clock edge.
    always @(*)
        assert(avail == (credits != 8'd0));
    always @(*)
        assert(full == (credits == F_MAX));

    always @(posedge clk) begin
        // CC-RESET: credits loads MAX.
        if (f_past_valid && !$past(rst_n))
            assert(credits == F_MAX);
        // CC-RESET: err clears.
        if (f_past_valid && !$past(rst_n))
            assert(!err);

        // CC-TAKE: take only, credits above zero, goes down by one.
        if (f_past_valid && $past(rst_n) && $past(take) && !$past(give)
                && ($past(credits) != 8'd0))
            assert(credits == ($past(credits) - 8'd1));

        // CC-GIVE: give only, credits below MAX, goes up by one.
        if (f_past_valid && $past(rst_n) && $past(give) && !$past(take)
                && ($past(credits) != F_MAX))
            assert(credits == ($past(credits) + 8'd1));

        // CC-BOTH: both high, credits unchanged (at zero and MAX too).
        if (f_past_valid && $past(rst_n) && $past(take) && $past(give))
            assert(credits == $past(credits));
        // CC-BOTH: nothing is refused, err unchanged.
        if (f_past_valid && $past(rst_n) && $past(take) && $past(give))
            assert(err == $past(err));

        // CC-IDLE: both low, credits unchanged.
        if (f_past_valid && $past(rst_n) && !$past(take) && !$past(give))
            assert(credits == $past(credits));

        // CC-UNDERFLOW: take only at zero, credits stays zero.
        if (f_past_valid && $past(rst_n) && $past(take) && !$past(give)
                && ($past(credits) == 8'd0))
            assert(credits == 8'd0);
        // CC-UNDERFLOW: err is set.
        if (f_past_valid && $past(rst_n) && $past(take) && !$past(give)
                && ($past(credits) == 8'd0))
            assert(err);

        // CC-OVERFLOW: give only at MAX, credits stays MAX.
        if (f_past_valid && $past(rst_n) && $past(give) && !$past(take)
                && ($past(credits) == F_MAX))
            assert(credits == F_MAX);
        // CC-OVERFLOW: err is set.
        if (f_past_valid && $past(rst_n) && $past(give) && !$past(take)
                && ($past(credits) == F_MAX))
            assert(err);

        // CC-ERR-STICKY: once set, err stays high until reset.
        if (f_past_valid && $past(rst_n) && $past(err))
            assert(err);

        // err port: err rises only when a take or a give is refused.
        if (f_past_valid && $past(rst_n) && !$past(err)
                && !($past(take) && !$past(give) && ($past(credits) == 8'd0))
                && !($past(give) && !$past(take) && ($past(credits) == F_MAX)))
            assert(!err);
    end

    // Scenarios the proof must still allow.
    always @(posedge clk) begin
        // Drained to zero.
        cover(f_past_valid && (credits == 8'd0));
        // Underflow refusal observed.
        cover(f_past_valid && $past(rst_n) && $past(take) && !$past(give)
              && ($past(credits) == 8'd0) && err);
        // Overflow refusal observed.
        cover(f_past_valid && $past(rst_n) && $past(give) && !$past(take)
              && ($past(credits) == F_MAX) && err);
        // Both at zero.
        cover(f_past_valid && $past(rst_n) && $past(take) && $past(give)
              && ($past(credits) == 8'd0));
        // Both at MAX.
        cover(f_past_valid && $past(rst_n) && $past(take) && $past(give)
              && ($past(credits) == F_MAX));
        // Refilled to full by a give.
        cover(f_past_valid && $past(rst_n) && $past(give) && !$past(take)
              && ($past(credits) != F_MAX) && full);
        // A normal take from full.
        cover(f_past_valid && $past(rst_n) && $past(take) && !$past(give)
              && ($past(credits) == F_MAX) && !err);
        // Idle cycle after reset.
        cover(f_past_valid && $past(rst_n) && !$past(take) && !$past(give)
              && !err);
        // Sticky err held while credits move away from MAX.
        cover(f_past_valid && $past(rst_n) && $past(err) && err
              && (credits != F_MAX));
        // Reset clears a set err.
        cover(f_past_valid && !$past(rst_n) && $past(err) && !err);
    end
endmodule
`default_nettype wire
=== END FILE ===
